const localeIndex: Record<Locale, number> = { en: -1, "pt-BR": 0, es: 1 };
function isLocale(value: unknown): value is Locale { return typeof value === "string" && supportedLocales.includes(value as Locale); }
function initialLocale(): Locale {
  try { const stored = localStorage.getItem(STORAGE_KEY); if (isLocale(stored)) return stored; } catch { /* storage may be unavailable */ }
  const languages = navigator.languages?.length ? navigator.languages : [navigator.language];
  for (const language of languages) { const normalized = language.toLowerCase(); if (normalized === "pt" || normalized.startsWith("pt-")) return "pt-BR"; if (normalized === "es" || normalized.startsWith("es-")) return "es"; if (normalized === "en" || normalized.startsWith("en-")) return "en"; }
  return "en";
}

interface I18nValue { locale: Locale; setLocale: (locale: Locale) => void; t: (source: string) => string; formatCurrency: (amount: number, currency?: string) => string; formatNumber: (value: number) => string; }
const I18nContext = createContext<I18nValue | null>(null);

function translate(source: string, locale: Locale): string { const item = entries[source]; return locale === "en" || !item ? source : item[localeIndex[locale]]; }
export function I18nProvider({ children }: { children: ReactNode }) {
  const [locale, setLocaleState] = useState<Locale>(initialLocale);
  const setLocale = (next: Locale) => { setLocaleState(next); try { localStorage.setItem(STORAGE_KEY, next); } catch { /* storage may be unavailable */ } };
  useLayoutEffect(() => {
    document.documentElement.lang = locale;
  }, [locale]);
  const value: I18nValue = { locale, setLocale, t: (source) => translate(source, locale), formatCurrency: (amount, currency = "USD") => new Intl.NumberFormat(locale, { style: "currency", currency }).format(amount), formatNumber: (number) => new Intl.NumberFormat(locale).format(number) };
  return <I18nContext value={value}>{children}</I18nContext>;
}

export function useI18n(): I18nValue { const context = useContext(I18nContext); if (!context) throw new Error("useI18n must be used within I18nProvider"); return context; }